    }
    if (txb_NewPw.getValue() != txb_NewRePw.getValue()) {
        $c.win.alert("비밀번호 확인 값이 틀립니다. 다시 입력하십시오. ");
        txb_NewRePw.focus();
        return false;
    }
    var regExp = /[\{\}\[\]\/?.,;:|\)*~`!^\-_+!=@\#$%&\\\=\('\"]/gi;
    var regExp1 = /[A-Z]/;
    var regExp2 = /[a-z]/;
    var regExp3 = /\d/;
    if (!regExp.test(txb_NewPw.getValue())) {
        $c.win.alert('특수문자는 필수입니다.');
        return false;

        //			if(!(regExp1.test(txb_NewPw.value)&&regExp2.test(txb_NewPw.value)&&regExp3.test(txb_NewPw.value))){			
        //				alert('영문(소문자), 영문(대문자),숫자, 특수문자 중 3가지 이상을 조합해야 합니다.');
        //				return false;
        //			}
    }
    var aes256Pw = scwin.fn_AES256(txb_NewPw.getValue());
    var aes256Id = scwin.fn_AES256(scwin.gUsrId);
    dts_basic.insertRow();
    var aesNewPw = scwin.fn_AES256(txb_NewPw.getValue());
    $c.stf.setObjectValue(txb_EncNewPw, aesNewPw);
    dts_basic.setCellData(1, "USR_ID", txb_UsrId.getValue());
    dts_basic.setCellData(1, "NEW_PW", txb_EncNewPw.getValue());
    trs_pass_check.Action = "/ListedCompanyPassword.do?method=getPwCheckResultStringPost";
    trs_pass_check.KeyName = "toinb_dataid4";
    //trs_pass_check.KeyValue="JSP(O:pOutput=dts_pwCheck,I:pInput=dts_usr_basic)";
    trs_pass_check.KeyValue = "JSP(O:pOutput=dts_pwCheck,I:pInput=dts_basic)";
    trs_pass_check.Post();
};
scwin.padString = function(source) {
    var paddingChar = ' ';
    var size = 32;
    var x = source.length % size;
    var padLength = size - x;
    for (var i = 0; i < padLength; i++) source += paddingChar;
    return source;
};


// 패킷 부분암호화 jackal_16.01.21
// AES 256 암호화
scwin.fn_AES256 = function(message) {
    var key = CryptoJS.enc.Hex.parse('000102030405060708090a0b0c0d0e0f');
    var iv = CryptoJS.enc.Hex.parse('101112131415161718191a1b1c1d1e1f');
    var padMsg = scwin.padString(message);
    var encrypted = CryptoJS.AES.encrypt(padMsg, key, {
        iv: iv,
        padding: CryptoJS.pad.NoPadding,
        mode: CryptoJS.mode.CBC
    });
    return encrypted;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

