//2020-12-16 KBoY 전화번호 체크
//true cases
// - 전화번호 1, 2, 3과 내선 번호 까지 모든값이 있는 경우.
// - 모든 값이 없는경우.
// - 내선번호만 없는 경우
//fase cases
// - 사무실번호 1,2,3중에 하나이상 있는데 하나이상 비워진경우.
// - 사무실번호는 없고, 내선만 있는경우.
scwin.isOkTelNo = function() {
    var isOk = false;
    var TEL_1 = txb_TelNo_1.getValue();
    var TEL_2 = txb_TelNo_2.getValue();
    var TEL_3 = txb_TelNo_3.getValue();
    var TEL_INNR = txb_TelInnrNo.getValue();

    //스페이스를 넣으면 안됨.
    if (scwin.spaceCheck(txb_TelNo_1) && scwin.spaceCheck(txb_TelNo_2) && scwin.spaceCheck(txb_TelNo_3) && scwin.spaceCheck(txb_TelInnrNo)) {
        //모든 값이 비어있다면 통과
        if (TEL_1 == '' && TEL_2 == '' && TEL_3 == '' && TEL_INNR == '') {
            isOk = true;
        } else {
            if (TEL_1 != '' && TEL_2 != '' && TEL_3 != '') {
                if (scwin.isOnlyNumber(txb_TelNo_1) && scwin.isOnlyNumber(txb_TelNo_2) && scwin.isOnlyNumber(txb_TelNo_3)) {
                    if (TEL_INNR == '') {
                        isOk = true;
                    } else {
                        if (scwin.isOnlyNumber(txb_TelInnrNo)) {
                            isOk = true;
                        } else isOk = false;
                    }
                } else {
                    isOk = false;
                }
            } else {
                $c.win.alert('전화번호 : [국번][앞번호][뒷번호]는 필수 입니다.');
                isOk = false;
            }
        }
    } else isOk = false;
    return isOk;
};
scwin.spaceCheck = function(telNoObj) {
    if ((telNoObj.getValue()).indexOf(" ") >= 0) {
        $c.win.alert("공백은 사용 할 수 없습니다.");
        telNoObj.focus();
        return false;
    }
    return true;
};


//2020-12-16 KBoY숫자체크
scwin.isOnlyNumber = function(telNoObj) {
    var pattern = /[0-9]/;
    var phoneNo = telNoObj.getValue();
    for (var i = 0; i < phoneNo.length; i++) {
        if (pattern.test(phoneNo.charAt(i)) == false) {
            $c.win.alert("전화번호는 숫자만 사용 가능합니다.");
            telNoObj.focus();
            return false;
        }
    }
    return true;
};
