scwin.dts_pwCheck_OnLoadCompleted = function(rowcount) {
    var result = dts_pwCheck.getCellData(1, "RESULT_STR");

    //1. replace 처리 (alert용으로 만들기 위해)
    result = $c.ut.replaceAll(result, '<br>', '\n');
    result = $c.ut.replaceAll(result, '&nbsp;', ' ');
    $c.win.alert(result);


    //3. 결과 처리
    if (result.indexOf("사용가능여부 : O") >= 0) {
        // 확인 성공시

        dts_basic.insertRow();
        dts_basic.setCellData(1, "USR_ID", txb_UsrId.getValue());
        if (txb_TelNo_1.getValue() != '') {
            dts_basic.setCellData(1, "TEL_NO", txb_TelNo_1.getValue() + '-' + txb_TelNo_2.getValue() + '-' + txb_TelNo_3.getValue());
        } else {
            dts_basic.setCellData(1, "TEL_NO", '');
        }
        dts_basic.setCellData(1, "TEL_NO_1", txb_TelNo_1.getValue());
        dts_basic.setCellData(1, "TEL_NO_2", txb_TelNo_2.getValue());
        dts_basic.setCellData(1, "TEL_NO_3", txb_TelNo_3.getValue());
        dts_basic.setCellData(1, "TEL_INNR_NO", txb_TelInnrNo.getValue());
        dts_basic.setCellData(1, "FAX_NO", txb_FaxNo.getValue());
        dts_basic.setCellData(1, "EMAIL", txb_Email.getValue());
        dts_basic.setCellData(1, "NEW_PW", txb_EncNewPw.getValue());
        var vAnswer = confirm($c.stf.getMessageParam("MSG-0004", ""));
        if (vAnswer == true) {
            if (scwin.isOkTelNo()) {
                trs_basic_modify.Action = "/Mypage.do?method=modifyUserInfo&inputMessageId=USER_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_basic_modify.KeyName = "toinb_dataid4";
                //trs_basic_modify.KeyValue="JSP(I:pInput=dts_usr_basic)";
                trs_basic_modify.KeyValue = "JSP(I:pInput=dts_basic)";
                trs_basic_modify.Post();
            }
        }
    } else {
        // 확인 실패시

    }
};
