    dts_dscl_noti.reset();
    dts_basic.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=USER_INOUT";
    dts_basic.reset();
    scwin.fn_getSessionData();

    // 기본정보 데이타 읽어오기
    fn_ReadBasicInfo();

    // hiddend값 감추기
    $c.stf.showObj(txb_Pw, false); // 이전 비밀번호
    $c.stf.showObj(txb_EncPw, false); // 이전 비밀번호 입력값 암호화
    $c.stf.showObj(txb_EncPrePw, false); // 이전 비밀번호 입력값 암호화
    $c.stf.showObj(txb_EncNewPw, false); // 새로운 비밀번호 암호화

    // 첫번째 탭 보이기
    tab_UsrInfo.setSelectedTabIndex(1);

    //alert( getMessageParamTwo("MSG-0001", "개인정보수정") );

};
